<?php
session_start(); require_once __DIR__.'/../php/sd_authorization.php'; sdRequireRole('technician');
require_once __DIR__.'/../php/conexao.php'; require_once __DIR__.'/../php/sd_service.php';
function reportEsc($x): string {return htmlspecialchars((string)$x,ENT_QUOTES,'UTF-8');}
$days=(int)($_GET['days']??30);if(!in_array($days,[7,30,90],true))$days=30;
$rows=[];$stats=[];$historical=[];$error='';
try{sdSchema($conexao);
 $sql="SELECT COALESCE(NULLIF(TRIM(assigned_to),''),'Não atribuído') responsavel, COUNT(*) total, SUM(status IN ('resolvido','fechado')) concluidos, SUM(status IN ('aberto','em_atendimento','aguardando')) pendentes, ROUND(AVG(CASE WHEN first_response_at IS NOT NULL THEN TIMESTAMPDIFF(MINUTE,created_at,first_response_at) END),1) resposta_media,ROUND(AVG(CASE WHEN resolved_at IS NOT NULL THEN TIMESTAMPDIFF(MINUTE,created_at,resolved_at) END),1) resolucao_media FROM sd_tickets WHERE created_at >= DATE_SUB(NOW(),INTERVAL ? DAY) GROUP BY COALESCE(NULLIF(TRIM(assigned_to),''),'Não atribuído') ORDER BY concluidos DESC,total DESC LIMIT 100";
 $st=$conexao->prepare($sql);$st->bind_param('i',$days);$st->execute();$rows=$st->get_result()->fetch_all(MYSQLI_ASSOC);$st->close();
 require_once __DIR__.'/../php/sd_productivity_history.php'; $historical=sdProductivityHistory($conexao,$days);
 $st=$conexao->prepare("SELECT COUNT(*) total,SUM(status IN ('resolvido','fechado')) concluidos, SUM(status IN ('aberto','em_atendimento','aguardando')) pendentes,COUNT(DISTINCT NULLIF(TRIM(assigned_to),'')) tecnicos FROM sd_tickets WHERE created_at >= DATE_SUB(NOW(),INTERVAL ? DAY)");$st->bind_param('i',$days);$st->execute();$stats=$st->get_result()->fetch_assoc();$st->close();
}catch(Throwable $e){error_log('sd productivity: '.$e->getMessage());$error='Não foi possível obter o relatório. Confirme o banco e o esquema do Service Desk.';}
?><!doctype html><html lang="pt-br"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CONFINTER — Produtividade técnica</title><link rel="stylesheet" href="../assets/css/sd.css"><link rel="stylesheet" href="../assets/css/confinter-sd-refinement.css"><link rel="stylesheet" href="assets/css/admin-ui.css"><link rel="stylesheet" href="assets/css/confinter-operations-2026.css"><link rel="stylesheet" href="assets/css/confinter-reporting.css"></head><body><?php include __DIR__.'/navbar.php';?><div class="page-wrapper"><main class="sd-wrap sd-admin-surface"><header><a href="service-desk.php">← Service Desk</a><h1>Produtividade da equipe</h1></header><p>Chamados abertos no período selecionado. Responsável atual; a transferência entre técnicos não é distribuída retroativamente. Médias em minutos corridos.</p><form method="get" class="report-filters"><label>Período <select name="days"><?php foreach([7,30,90] as $n):?><option value="<?=$n?>" <?=$days===$n?'selected':''?>>Últimos <?=$n?> dias</option><?php endforeach;?></select></label><button>Aplicar</button></form><?php if($error):?><p class="notice" role="alert"><?=reportEsc($error)?></p><?php else:?><div class="sd-metrics"><article><strong><?=reportEsc($stats['total']??0)?></strong><span>Chamados no período</span></article><article><strong><?=reportEsc($stats['concluidos']??0)?></strong><span>Concluídos</span></article><article><strong><?=reportEsc($stats['pendentes']??0)?></strong><span>Pendentes</span></article><article><strong><?=reportEsc($stats['tecnicos']??0)?></strong><span>Responsáveis distintos</span></article></div><section class="sd-card"><h2>Desempenho por responsável</h2><div class="sd-table-scroll"><table><thead><tr><th>Responsável</th><th>Chamados</th><th>Concluídos</th><th>Pendentes</th><th>Resposta média (min)</th><th>Resolução média (min)</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><?php foreach(['responsavel','total','concluidos','pendentes','resposta_media','resolucao_media'] as $k):?><td><?=reportEsc($r[$k]??'—')?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div><?php if(!$rows):?><p>Nenhum chamado encontrado.</p><?php endif;?></section><section class="sd-card"><h2>Participação histórica por técnico</h2><p>Intervalos estimados a partir de mudanças registradas em <code>sd_ticket_history</code>. Participações não são horas de trabalho efetivo; períodos sem responsável são classificados como não atribuídos. Registros anteriores à adoção do histórico completo podem ser incompletos.</p><div class="sd-table-scroll"><table><thead><tr><th>Técnico</th><th>Chamados em que participou</th><th>Minutos atribuídos</th><th>Resoluções creditadas</th></tr></thead><tbody><?php foreach($historical as $hr):?><tr><td><?=reportEsc($hr['responsavel'])?></td><td><?=reportEsc($hr['chamados'])?></td><td><?=reportEsc($hr['minutos'])?></td><td><?=reportEsc($hr['conclusoes'])?></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?></main></div><?php include __DIR__.'/footer.php'; ?></body></html>